import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"Importable sample: GitHub Actions vertical slice (P3-04)","description":"","frontmatter":{},"headers":[],"relativePath":"samples/declarative-vertical-sample.md","filePath":"samples/declarative-vertical-sample.md"}'),r={name:"samples/declarative-vertical-sample.md"};function l(s,e,c,d,n,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="importable-sample-github-actions-vertical-slice-p3-04" tabindex="-1">Importable sample: GitHub Actions vertical slice (P3-04) <a class="header-anchor" href="#importable-sample-github-actions-vertical-slice-p3-04" aria-label="Permalink to &quot;Importable sample: GitHub Actions vertical slice (P3-04)&quot;">​</a></h1><p><code>declarative-vertical-sample.json</code> is a <strong>config bundle</strong> (same format as Settings → Advanced → Import/Export) demonstrating one vertical declarative loop: a single <code>github.actions.runs</code> state feeds the L0 tile, the L2 panel row, and the L3 detail from the same source of truth, while the L3 detail additionally aggregates a second source (<code>http.quota</code>) to demonstrate cross-source bindings and missing-source display.</p><h2 id="what-is-inside" tabindex="-1">What is inside <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to &quot;What is inside&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td><code>w-sample-ci</code></td><td>GitHub Actions run card: tile / row / detail faces all declarative; detail aggregates the quota source</td></tr><tr><td><code>w-sample-quota</code></td><td><code>http.quota</code> card: points at the public GitHub <code>rate_limit</code> endpoint, works without any credential; its detail face is an HTML carrier face (controlled subset, 2026-10-17 ruling)</td></tr><tr><td><code>conn-sample-github</code></td><td>GitHub connection: bundle carries a credentialRef only; enter your PAT after importing</td></tr><tr><td><code>conn-sample-quota</code></td><td>HTTP connection: replace with any JSON quota endpoint you like</td></tr><tr><td><code>open-quota-doc</code></td><td>Bundled action (open.url): referenced by the HTML face button&#39;s <code>data-action</code>; clickable right after import</td></tr></tbody></table><h2 id="how-to-use" tabindex="-1">How to use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to use&quot;">​</a></h2><ol><li><strong>Back up first</strong>: importing replaces all five config files (including the action library) — run Settings → Advanced → Export first.</li><li>Settings → Advanced → Import configuration, pick this file.</li><li>On the connections page enter a PAT for <code>conn-sample-github</code>; change <code>repository</code> / <code>workflow</code> of <code>w-sample-ci</code> to your repo.</li><li>Pin it and walk the three faces: tile (L0) → panel row (L2) → detail (L3); one state, three consistent views.</li></ol><h2 id="what-to-verify" tabindex="-1">What to verify <a class="header-anchor" href="#what-to-verify" aria-label="Permalink to &quot;What to verify&quot;">​</a></h2><ul><li>[ ] No C# changes: edit only the JSON component trees; saving updates the target face immediately (save redraws without refetching).</li><li>[ ] Three faces, one source: L0 / L2 / L3 all show the same <code>w-sample-ci</code> state.</li><li>[ ] Two independent sources: quota refreshes never trigger CI fetches; the QUOTA section in detail updates on its own cadence.</li><li>[ ] Missing-source display: disable or delete <code>w-sample-quota</code> and the QUOTA section shows &quot;⚠ 缺少数据源：quota&quot; — no faked zeros, no stale healthy values; it refills automatically once restored.</li><li>[ ] Clear-to-fallback: remove the <code>components</code> / <code>sources</code> keys and save; all three faces return to traditional rendering.</li><li>[ ] Offline / recovery: while offline the tile and detail show stale timestamps and self-heal after reconnection.</li><li>[ ] HTML face fallback: delete <code>open-quota-doc</code> from the action library and re-import; the detail&#39;s button slot degrades to a &quot;⚠ 动作不可用&quot; diagnostic placeholder while the other faces keep working.</li></ul><p>The runtime items above require acceptance on real Windows. The CI structural gate is kept evergreen by <code>DeclarativeSampleTests</code>: trees and sources validate, additional sources close over bundled widgets, and the file carries no secret-like tokens; the HTML carrier face parses through the closed vocabulary and its <code>data-action</code> closes over bundled actions.</p>',9)])])}const m=t(r,[["render",l]]);export{p as __pageData,m as default};
